gMY(){return"\u0623\u064a\u0642\u0648\u0646\u0629 \u0627\u0644\u0645\u062d\u0627\u062f\u062b\u0629 \u0627\u0644\u0639\u0627\u0626\u0645\u0629 \u0627\u0644\u062a\u064a \u062a\u062c\u064a\u0628 \u0639\u0644\u0649 \u0623\u0633\u0626\u0644\u0629 \u062d\u0648\u0644 \u0627\u0644\u062a\u0637\u0628\u064a\u0642. \u0623\u0648\u0642\u0641\u0647\u0627 \u0625\u0630\u0627 \u0643\u0627\u0646\u062a \u062a\u0632\u0639\u062c\u0643 \u2014 \u0647\u0630\u0627 \u064a\u0624\u062b\u0631 \u0639\u0644\u0649 \u062d\u0633\u0627\u0628\u0643 \u0641\u0642\u0637\u060c \u0648\u0644\u064a\u0633 \u0639\u0644\u0649 \u0632\u0645\u0644\u0627\u0626\u0643."},
gNf(){return"\u0627\u0644\u0644\u063a\u0629"},
gNg(){return"\u0627\u062e\u062a\u0631 \u0627\u0644\u0644\u063a\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u0629 \u0641\u064a \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0628\u0627\u0644\u0643\u0627\u0645\u0644."},
ga0I(){return"\u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0627\u0644\u0646\u0634\u0637\u0629"},
ga0Q(){return"\u0627\u0644\u0637\u0644\u0628\u0627\u062a \u0627\u0644\u0645\u0639\u0644\u0642\u0629"},
