ga0O(){return"\u062d\u0627\u0644\u0629 \u062c\u062f\u064a\u062f\u0629"},
ga0S(){return"\u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0627\u0644\u0623\u062e\u064a\u0631\u0629 \u0648\u0627\u0644\u0642\u0627\u062f\u0645\u0629"},
ga0P(){return"\u0644\u0627 \u062a\u0648\u062c\u062f \u062d\u0627\u0644\u0627\u062a \u0628\u0639\u062f."},
gVO(){return"\u0644\u0648\u062d\u0629 \u0627\u0644\u062d\u0627\u0644\u0627\u062a"},
