gVC(){return"\u0645\u0633\u062d QR"},
gFk(){return"\u0645\u0633\u062d \u0644\u0644\u062a\u0631\u0642\u064a\u0629"},
gFj(){return"\u0648\u062c\u0651\u0647 \u0627\u0644\u0643\u0627\u0645\u064a\u0631\u0627 \u0646\u062d\u0648 \u0631\u0645\u0632 QR \u0627\u0644\u0645\u0637\u0628\u0648\u0639 \u0639\u0644\u0649 \u0627\u0644\u062d\u0627\u0644\u0629 \u2014 \u0633\u062a\u0646\u062a\u0642\u0644 \u062a\u0644\u0642\u0627\u0626\u064a\u064b\u0627 \u0625\u0644\u0649 \u0627\u0644\u0645\u0631\u062d\u0644\u0629 \u0627\u0644\u062a\u0627\u0644\u064a\u0629."},
