gMx(){return"\u06a9\u06d5\u06cc\u0633\u06d5 \u062f\u0648\u0648\u0628\u0627\u0631\u06d5\u06a9\u0631\u0627\u0648\u06d5\u06a9\u0627\u0646 \u0644\u06d5 \u0646\u06cc\u0633\u0628\u06d5\u06cc \u0647\u06cc\u0686 \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f\u06ce\u06a9 \u0646\u0627\u0698\u0645\u06ce\u0631\u062f\u0631\u06ce\u0646. \u0644\u06d5\u0633\u06d5\u0631 \u0626\u06d5\u0648 \u0645\u0627\u0646\u06af\u0627\u0646\u06d5\u06cc \u0645\u0648\u0648\u0686\u06d5 \u062c\u06ce\u0628\u06d5\u062c\u06ce \u062f\u06d5\u0628\u06ce\u062a \u06a9\u06d5 \u0644\u06d5 \u0626\u06ce\u0633\u062a\u0627\u0648\u06d5 \u062f\u0631\u0648\u0633\u062a \u062f\u06d5\u06a9\u0631\u06ce\u0646."},
yQ(a){return"\u0628\u0695\u06cc \u067e\u06ce\u0648\u06cc\u0633\u062a \u0644\u06d5 \u06a9\u06c6\u06af\u0627\u062f\u0627 \u0646\u06cc\u06cc\u06d5 (\u0645\u0627\u0648\u06d5 "+a+") \u2014 \u0633\u06d5\u0631\u06d5\u062a\u0627 \u067e\u0633\u0648\u0648\u0644\u06d5\u06cc \u06a9\u0695\u06cc\u0646 \u062a\u06c6\u0645\u0627\u0631 \u0628\u06a9\u06d5."},
