gM9(){return"\u0631\u06ce\u062f\u0627\u0646 \u0628 \u06a4\u06cc\u062f\u06cc\u06c6\u06cc\u0627\u0646"},
gMa(){return"\u0628\u06c6 \u0644\u0642\u06d5\u06a9\u06ce \u0646\u0648\u06cc \u0628 \u0634\u06ce\u0648\u06d5\u06cc\u06d5\u06a9\u06ce \u0628\u0646\u06d5\u0695\u06d5\u062a \u06a4\u06d5\u0645\u0631\u0627\u06cc\u06d5 \u2014 \u06a4\u06cc\u062f\u06cc\u06c6 \u0628\u06d5\u0631\u06cc \u0628\u0627\u0631\u06a9\u0631\u0646\u06ce \u0646\u0627\u0647\u06ce\u062a\u06d5 \u0628\u0686\u0648\u0648\u06a9\u06a9\u0631\u0646\u060c \u0644\u06d5\u0648\u0645\u0627 \u0645\u06d5\u0632\u0646\u062a\u0631\u06cc\u0646 \u0626\u06d5\u06af\u06d5\u0631\u06d5 \u0628\u06c6 \u062a\u0698\u06cc\u0628\u0648\u0648\u0646\u0627 \u0633\u0646\u0648\u0648\u0631\u06ce \u0628\u06d5\u0644\u0627\u0634 \u06cc\u06ce Supabase."},
gM_(){return"\u0631\u06ce\u062f\u0627\u0646 \u0628 \u062a\u06ce\u0628\u06cc\u0646\u06cc\u06ce\u0646 \u062f\u06d5\u0646\u06af\u06cc"},
gM0(){return"\u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u0646\u0627 \u062a\u06ce\u0628\u06cc\u0646\u06cc\u06ce\u0646 \u062f\u06d5\u0646\u06af\u06cc \u062f \u0646\u0627\u0645\u06d5\u06cc\u06ce\u0646 \u06a9\u06d5\u06cc\u0633\u0627\u0646 \u062f\u0627."},
gM3(){return"\u0631\u06ce\u062f\u0627\u0646 \u0628 \u0628\u06d5\u0644\u06af\u06d5\u0646\u0627\u0645\u06d5\u06cc\u0627\u0646"},
gM4(){return"\u067e\u0627\u0634\u06a9\u06c6\u06cc\u06ce\u0646 PDF/\u0633\u06a9\u0627\u0646\u06cc \u2014 \u0631\u06d5\u0686\u06d5\u062a\u06d5\u060c \u0641\u06c6\u0631\u0645\u06ce\u0646 \u0628\u06cc\u0645\u06d5\u06cc\u06ce \u0648 \u06cc\u06ce\u0646 \u0648\u06d5\u06a9\u06cc \u0648\u0627\u0646."},
gNS(){return"\u067e\u0627\u0634\u06d5\u06a9\u06d5\u0641\u062a\u06a9\u0631\u0646\u0627 \u0631\u06ce\u06a9\u062e\u0633\u062a\u0646\u06ce\u0646 \u0644\u0642\u06cc"},
gOd(){return"\u0634\u06ce\u0648\u0627\u0632\u06ce \u0646\u06d5\u062e\u0634\u06ce \u062f\u062f\u0627\u0646\u0627\u0646"},
gOf(){return"\u0698\u0645\u0627\u0631\u06ce\u0646 \u062f\u062f\u0627\u0646\u0627\u0646 \u0686\u0627\u0648\u0627 \u0644 \u0633\u06d5\u0631 \u0646\u06d5\u062e\u0634\u06d5\u060c \u06a9\u0627\u0631\u062a\u06ce\u0646 \u06a9\u06d5\u06cc\u0633\u0627\u0646 \u0648 \u062e\u0634\u062a\u06d5\u06cc\u0627\u0646 \u062f\u06cc\u0627\u0631 \u062f\u0628\u0646 \u2014 \u0626\u06d5\u06a4\u06d5 \u062a\u0646\u06ce \u0647\u06d5\u0644\u0628\u0698\u0627\u0631\u062a\u0646\u0627 \u067e\u06cc\u0634\u0627\u0646\u062f\u0627\u0646\u06ce\u06cc\u06d5\u060c \u0686 \u062a\u0634\u062a \u0628 \u0631\u06d5\u0646\u06af\u06d5\u06a9\u06ce \u062f\u06cc \u0646\u0627\u0647\u06ce\u062a\u06d5 \u067e\u0627\u0634\u06d5\u06a9\u06d5\u0641\u062a\u06a9\u0631\u0646."},
gOc(){return"\u0698\u0645\u0627\u0631\u06ce\u0646 FDI"},
gOe(){return"\u067e\u06cc\u062a\u06ce\u0646 \u0686\u0627\u0631\u06d5\u06a9\u0627\u0646"},
gOa(){return"\u0646\u0645\u0648\u0648\u0646\u06d5: 11\u060c 12\u060c 24\u060c 46"},
gOb(){return"\u0646\u0645\u0648\u0648\u0646\u06d5: UR1\u060c UR2\u060c UL4\u060c LR6"},
gMX(){return"\u067e\u06cc\u0634\u0627\u0646\u062f\u0627\u0646\u0627 \u062f\u0648\u06af\u0645\u06d5\u06cc\u0627 \u0686\u0627\u062a\u0627 \u0647\u0627\u0631\u06cc\u06a9\u0627\u0631\u06cc\u06ce"},
gMY(){return"\u0626\u0627\u06cc\u06a9\u06c6\u0646\u0627 \u0686\u0627\u062a\u06ce \u06cc\u0627 \u0644\u06a4\u06c6\u06a9 \u06cc\u0627 \u0628\u06d5\u0631\u0633\u06a4\u0627 \u067e\u0633\u06cc\u0627\u0631\u06ce\u0646 \u062f\u06d5\u0631\u0628\u0627\u0631\u06d5\u06cc \u0626\u06d5\u067e\u06cc \u062f\u062f\u06d5\u062a. \u0626\u06d5\u06af\u06d5\u0631 \u0631\u06ce\u06af\u0631 \u0628\u06cc\u062a \u0628\u06cc\u0645\u0631\u06cc\u0646\u06d5 \u2014 \u0626\u06d5\u06a4\u06d5 \u062a\u0646\u06ce \u0644 \u0633\u06d5\u0631 \u0647\u06d5\u0698\u0645\u0627\u0631\u0627 \u062a\u06d5 \u06a9\u0627\u0631 \u062f\u06a9\u06d5\u062a\u060c \u0646\u06d5 \u06cc\u06ce\u0646 \u0647\u06d5\u06a4\u0627\u0644\u06ce\u0646 \u062a\u06d5."},
gNf(){return"\u0632\u0645\u0627\u0646"},
gNg(){return"\u0626\u06d5\u0648 \u0632\u0645\u0627\u0646\u06ce \u062f \u0647\u06d5\u0645\u06cc \u0626\u06d5\u067e\u06cc \u062f\u0627 \u062f\u0647\u06ce\u062a\u06d5 \u0628\u06a9\u0627\u0631\u0626\u06cc\u0646\u0627\u0646 \u0647\u06d5\u0644\u0628\u0698\u06ce\u0631\u06d5."},
ga0I(){return"\u06a9\u06d5\u06cc\u0633\u06ce\u0646 \u0686\u0627\u0644\u0627\u06a9"},
ga0Q(){return"\u062f\u0627\u062e\u0648\u0627\u0632\u06cc\u06ce\u0646 \u0644 \u0647\u06cc\u06a4\u06cc\u06ce"},
gGv(){return"\u062f\u06d5\u0645 \u0628\u06c6\u0631\u06cc"},
ga0R(){return"\u0626\u0627\u0645\u0627\u062f\u06d5 \u0628\u06c6 \u0648\u06d5\u0631\u06af\u0631\u062a\u0646\u06ce"},
ga0U(){return"\u062f\u06cc\u062a\u0646\u06d5\u06a9\u0627 \u06af\u0634\u062a\u06cc \u06cc\u0627 \u06a9\u0627\u0631\u06af\u06d5\u0647\u06ce"},
ga0T(){return"\u062f\u0627\u0634\u0628\u06c6\u0631\u062f"},
ga0O(){return"\u06a9\u06d5\u06cc\u0633\u06ce \u0646\u0648\u06cc"},
ga0S(){return"\u06a9\u06d5\u06cc\u0633\u06ce\u0646 \u062f\u0648\u0645\u0627\u0647\u06cc\u06ce \u0648 \u06cc\u06ce\u0646 \u062f\u0647\u06ce\u0646"},
ga0P(){return"\u0647\u06ce\u0634\u062a\u0627 \u0686 \u06a9\u06d5\u06cc\u0633 \u0646\u06cc\u0646\u0646."},
gVO(){return"\u062a\u06d5\u062e\u062a\u06ce \u06a9\u06d5\u06cc\u0633\u0627\u0646"},
gVN(){return"\u0628\u06c6 \u062f\u06cc\u062a\u0646\u0627 \u0647\u06d5\u0645\u06cc \u0642\u06c6\u0646\u0627\u063a\u0627\u0646 \u0633\u06a9\u0631\u06c6\u0644 \u0628\u06a9\u06d5 \u06cc\u0627\u0646 \u062a\u06cc\u0631\u0627\u0646 \u0628\u06a9\u0627\u0631\u0628\u06cc\u0646\u06d5\u061b \u0647\u06d5\u0631 \u0633\u062a\u0648\u06cc\u0646\u06d5\u06a9 \u06a9\u0627\u0631\u062a\u06ce\u0646 \u062e\u06c6 \u0628 \u062e\u06c6 \u0633\u06a9\u0631\u06c6\u0644 \u062f\u06a9\u06d5\u062a."},
gVz(){return"\u06a9\u06d5\u06cc\u0633\u06ce \u0646\u0648\u06cc"},
VL(a){return"\u062f\u0648\u0645\u0627\u0647\u06cc\u06a9 "+a+" \u0631\u06c6\u0698"},
