gFj(){return"\u06a9\u0627\u0645\u06ce\u0631\u0627\u06cc\u06ce \u0628\u06d5\u0631\u06d5\u06a4 \u06a9\u06c6\u062f\u06ce QR \u06cc\u06ce \u0686\u0627\u067e\u06a9\u0631\u06cc \u06cc\u06ce \u06a9\u06d5\u06cc\u0633\u06cc \u0628\u06a9\u06d5 \u2014 \u0628 \u062e\u06c6 \u0642\u06c6\u0646\u0627\u063a\u06d5\u06a9\u06ce \u067e\u06ce\u0634\u06a4\u06d5 \u062f\u0686\u06cc\u062a."},
gVE(){return"\u0642\u06c6\u0646\u0627\u063a\u0627 \u067e\u0627\u0634\u062a\u0631"},
