gMp(){return"\u0647\u06d5\u0644\u06a9\u0631\u06cc: \u0646\u0627\u06a4 \u0648 \u0646\u0627\u06a4\u0646\u06cc\u0634\u0627\u0646\u06ce \u062a\u0627\u0642\u06cc\u06af\u06d5\u0647\u06ce \u0644 \u0633\u06d5\u0631\u06cc \u067e\u0633\u0648\u0648\u0644\u06d5\u060c \u0644\u06cc\u0633\u062a\u06ce\u0646 \u06a9\u06d5\u06cc\u0633\u0627\u0646 \u0648 \u06a9\u06d5\u0634\u0641\u0627\u0646 \u0646\u0627\u06a4\u06d5\u0631\u0627\u0633\u062a \u062f\u0628\u0646\u060c \u0648 \u0646\u0627\u06a4 \u0648 \u062f\u06cc\u0631\u06c6\u06a9\u0627 \u0628\u06d5\u0644\u06af\u06d5\u0646\u0627\u0645\u06ce \u0644 \u0628\u0646 \u0648\u0627\u0646 \u0646\u0627\u06a4\u06d5\u0631\u0627\u0633\u062a \u062f\u0628\u0646."},
gNe(){return"\u062f\u062f\u0627\u0646 \u0644 \u0633\u06d5\u0631 \u0644\u06ce\u0628\u0644\u06ce \u06a9\u06d5\u06cc\u0633\u06cc \u0648\u06d5\u06a9 \u0646\u06d5\u062e\u0634\u06d5\u06a9\u06ce \u062e\u0627\u0686\u06cc"},
gNd(){return"\u0647\u06d5\u0644\u06a9\u0631\u06cc: \u0644\u06ce\u0628\u0644 \u062f\u062f\u0627\u0646\u0627\u0646 \u062f \u0686\u0627\u0631 \u0686\u0627\u0631\u06d5\u06a9\u0627\u0646 \u062f\u0627 \u0644 \u062f\u06c6\u0631 \xab+\xbb \u067e\u06cc\u0634\u0627\u0646 \u062f\u062f\u06d5\u062a (\u0633\u06d5\u0631\u06cc \u0631\u0627\u0633\u062a | \u0633\u06d5\u0631\u06cc \u0686\u06d5\u067e \u0644 \u0633\u06d5\u0631 \u062e\u0648\u0627\u0631\u06ce \u0631\u0627\u0633\u062a | \u062e\u0648\u0627\u0631\u06ce \u0686\u06d5\u067e)\u060c \u0648\u06d5\u06a9 \u0644 \u0633\u06d5\u0631 \u067e\u0633\u0648\u0648\u0644\u0627 \u062a\u0627\u0642\u06cc\u06af\u06d5\u0647\u06ce. \u06a4\u06d5\u0645\u0631\u0627\u06cc: \u0626\u06ce\u06a9 \u0647\u06ce\u0644\u0627 \u0698\u0645\u0627\u0631\u06d5 \u06cc\u0627\u0646 \u067e\u06cc\u062a\u06ce\u0646 \u062f\u062f\u0627\u0646\u0627\u0646."},
gNQ(){return"\u0633\u06a9\u0627\u0646\u06d5\u0631\u06ce \u062a\u0627\u0642\u06cc\u06af\u06d5\u0647\u06ce \u062f \u06a9\u06d5\u06cc\u0633\u06ce \u0646\u0648\u06cc \u062f\u0627 \u067e\u06ce\u062f\u06a4\u06cc\u06d5"},
gNR(){return"\u06a9\u06d5\u06cc\u0633 \u0646\u0627\u0628\u06cc\u062a \u0628\u0647\u06ce\u062a\u06d5 \u062f\u0631\u0648\u0633\u062a\u06a9\u0631\u0646 \u0647\u06d5\u062a\u0627 \u0633\u06a9\u0627\u0646\u06d5\u0631\u06d5\u06a9\u060c \u06cc\u0627\u0646 \xab\u062f\u06d5\u0631\u06d5\u06a9\u06cc\xbb \u0628\u06c6 \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u06ce \u0698\u0644\u0627\u06cc\u06ce \u062a\u0627\u0642\u06cc\u06af\u06d5\u0647\u06ce \u0646\u06d5\u0647\u0627\u062a\u06cc\u06d5 \u0633\u06a9\u0627\u0646\u06a9\u0631\u0646\u060c \u0628\u0647\u06ce\u062a\u06d5 \u0647\u06d5\u0644\u0628\u0698\u0627\u0631\u062a\u0646."},
gNB(){return"\u062f\u062f\u0627\u0646 \u0648\u06d5\u06a9 \u067e\u06cc\u062a\u06ce\u0646 \u0686\u0627\u0631\u06d5\u06a9\u0627\u0646 \u0644 \u0633\u06d5\u0631 \u0686\u0627\u067e\u06a9\u0631\u0646\u0627\u0646 (UL1)"},
gNA(){return"\u0647\u06d5\u0644\u06a9\u0631\u06cc: \u0644\u06ce\u0628\u0644\u06ce\u0646 \u06a9\u06d5\u06cc\u0633\u0627\u0646 \u0648 \u062a\u06a9\u06ce\u062a\u06ce\u0646 \u0648\u06d5\u0631\u06af\u0631\u062a\u0646\u06ce \u062f\u062f\u0627\u0646\u0627\u0646 \u0648\u06d5\u06a9 UL1\u060c UR2\u2026 \u062f\u0646\u06a4\u06cc\u0633\u0646 \u0644 \u062c\u0647\u06ce \u0698\u0645\u0627\u0631\u06ce\u0646 FDI (21\u060c 12\u2026)."},
gMl(){return"\u0644\u06ce\u0628\u0644\u06ce \u06a9\u06d5\u06cc\u0633\u06cc \u06cc\u06ce \u0628\u0686\u0648\u0648\u06a9 (A6\u060c 4 \u0644 \u0633\u06d5\u0631 \u067e\u06d5\u0631\u06d5\u06a9\u06ce A4)"},
gMk(){return"\u0647\u06d5\u0644\u06a9\u0631\u06cc: \u0644\u06ce\u0628\u0644\u06ce \u06a9\u06d5\u06cc\u0633\u06cc \u0686\u0627\u0631\u06d5\u06a9\u06d5\u06a9\u0627 A4 \u0640\u06d5 \u0628 \u0647\u06d5\u0645\u0627\u0646 \u0642\u06d5\u0628\u0627\u0631\u06ce \u0646\u06a4\u06cc\u0633\u06cc\u0646\u06ce\u060c \u0644\u06d5\u0648\u0645\u0627 \u062f\u06d5\u0645\u06ce 4 \u0644 \u0633\u06d5\u0631 \u067e\u06d5\u0631\u06d5\u06a9\u06ce \u062f\u0647\u06ce\u0646\u06d5 \u0686\u0627\u067e\u06a9\u0631\u0646 \u0646\u06a4\u06cc\u0633\u06cc\u0646 \u0628 \u0642\u06d5\u0628\u0627\u0631\u06ce \u062a\u06d5\u0645\u0627\u0645 \u062f\u06d5\u0631\u062f\u06a9\u06d5\u06a4\u06cc\u062a \u0646\u06d5 \u0628\u0686\u0648\u0648\u06a9\u06a9\u0631\u06cc. \u0647\u06d5\u0631\u0648\u06d5\u0633\u0627 \u0628\u06c6 \u0686\u0627\u067e\u06a9\u06d5\u0631\u06ce\u0646 \u0644\u06ce\u0628\u0644\u06ce\u0646 4x6 \u0626\u06cc\u0646\u0686\u06cc \u062f\u06af\u0648\u0646\u062c\u06cc\u062a."},
